using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Diagnostics;using System.Windows.Forms;
class CgTransitionChecks {
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static object Get(Game g,string n){return typeof(Game).GetField(n,flags).GetValue(g);}static void Set(Game g,string n,object v){typeof(Game).GetField(n,flags).SetValue(g,v);}static void Call(Game g,string n){typeof(Game).GetMethod(n,flags).Invoke(g,null);}
 [STAThread] static void Main(){using(var g=new Game()){g.Opacity=0;g.Show();g.Size=new Size(1900,1030);var c=((System.Collections.Generic.List<Chapter>)Get(g,"chapters")).Single(TavernStory.Is);var s=new Save();foreach(var flag in new[]{TavernStory.ScriptFlag,TavernStory.WaystationFlag,TavernStory.OpeningFlag})s.storyFlags.Add(flag);Set(g,"save",s);Set(g,"current",c);Set(g,"index",12);Call(g,"ShowGoddessTransfer");Application.DoEvents();var content=(Control)Get(g,"content");var cg=content.Controls.OfType<OpeningCgCanvas>().Single();var preloadUntil=DateTime.UtcNow.AddSeconds(1);while(DateTime.UtcNow<preloadUntil){Application.DoEvents();System.Threading.Thread.Sleep(10);}var clock=Stopwatch.StartNew();cg.Completed();double preparation=clock.Elapsed.TotalMilliseconds;Application.DoEvents();var stage=(ArtPanel)Get(g,"stage");var reveal=content.Controls.OfType<WhiteSceneReveal>().Single();if(reveal.Bounds!=content.ClientRectangle||reveal.Size!=stage.Size)throw new Exception("Transition compresses scene or excludes dialogue");int builds=stage.SceneBuilds,frames=0;double maximum=0;using(var frame=new Bitmap(reveal.Width,reveal.Height)){var end=DateTime.UtcNow.AddSeconds(3);while(!reveal.IsDisposed&&DateTime.UtcNow<end){var paint=Stopwatch.StartNew();reveal.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));maximum=Math.Max(maximum,paint.Elapsed.TotalMilliseconds);if(frames==3)frame.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"transfer-fullscreen.png"));frames++;Application.DoEvents();System.Threading.Thread.Sleep(15);}}Call(g,"StopAudio");if(!reveal.IsDisposed||frames<5||stage.SceneBuilds>builds+1)throw new Exception("Transition rendering regression");Console.WriteLine("PASS: full-screen bounds, single dialogue, "+frames+" frames, max paint "+maximum.ToString("F1")+"ms, preparation "+preparation.ToString("F1")+"ms");g.Close();}}
}
